import hashlib
import re
from collections import defaultdict
from pathlib import Path
from typing import Any


class DuplicateDetector:
    """Detect code duplication using token n-gram fingerprinting.

    Approach: For each Python source file, extract significant tokens
    (identifiers, keywords, operators) and compute n-gram hashes.
    Files sharing a high proportion of n-gram hashes are considered duplicate.

    Returns a duplication percentage for the overall codebase.
    No external dependencies — pure Python, std-lib only.
    """

    # Number of tokens per n-gram
    NGRAM_SIZE = 5
    # Similarity threshold above which files are considered duplicates
    SIMILARITY_THRESHOLD = 0.7
    # Minimum file size (in tokens) for duplication checking
    MIN_TOKENS = 30

    @classmethod
    def detect(cls, files: list[dict], repo_root: Path | str | None = None) -> dict[str, Any]:
        """Run duplication detection across all files.

        Args:
            files: List of {path, ...} dicts from _extract_source_files()
            repo_root: Optional root directory for resolving file paths

        Returns: {
            "duplication_percentage": float,  # 0-100
            "duplicate_groups": [  # Groups of similar files
                { "files": ["path1", "path2"], "similarity": 0.85 }
            ],
            "analyzed_files": int,
            "duplicate_files": int,
        }
        """
        if not files:
            return {"duplication_percentage": 0, "duplicate_groups": [], "analyzed_files": 0, "duplicate_files": 0}

        # Only analyze Python files
        py_files = [f for f in files if f.get("ext", "") == ".py"]
        if not py_files:
            return {"duplication_percentage": 0, "duplicate_groups": [], "analyzed_files": 0, "duplicate_files": 0}

        # Compute n-gram fingerprints for each file
        fingerprints: dict[str, set[str]] = {}

        for f in py_files:
            file_path = Path(f["path"])
            fingerprints[str(file_path)] = set()

            # If repo_root is available, try to read the file
            content = None
            if repo_root:
                full_path = Path(repo_root) / file_path
                try:
                    if full_path.exists():
                        content = full_path.read_text(encoding="utf-8", errors="replace")
                except Exception:
                    pass

            if content:
                tokens = cls._tokenize(content)
                if len(tokens) >= cls.MIN_TOKENS:
                    fingerprints[str(file_path)] = cls._compute_ngrams(tokens)

        if not fingerprints:
            return {"duplication_percentage": 0, "duplicate_groups": [], "analyzed_files": 0, "duplicate_files": 0}

        # Pairwise similarity comparison
        analyzed = list(fingerprints.items())
        duplicate_groups = []
        duplicate_file_paths: set[str] = set()

        for i in range(len(analyzed)):
            for j in range(i + 1, len(analyzed)):
                path_a, grams_a = analyzed[i]
                path_b, grams_b = analyzed[j]

                if not grams_a or not grams_b:
                    continue

                similarity = cls._jaccard_similarity(grams_a, grams_b)
                if similarity >= cls.SIMILARITY_THRESHOLD:
                    duplicate_groups.append({
                        "files": [path_a, path_b],
                        "similarity": round(similarity, 2),
                    })
                    duplicate_file_paths.add(path_a)
                    duplicate_file_paths.add(path_b)

        # Calculate duplication percentage
        total_files = len(analyzed)
        duplicate_count = len(duplicate_file_paths)
        duplication_pct = (duplicate_count / total_files * 100) if total_files > 0 else 0

        return {
            "duplication_percentage": round(duplication_pct, 1),
            "duplicate_groups": duplicate_groups,
            "analyzed_files": total_files,
            "duplicate_files": duplicate_count,
        }

    @staticmethod
    def _tokenize(content: str) -> list[str]:
        """Extract significant tokens from source code."""
        # Remove comments and strings
        content = re.sub(r'#.*$', '', content, flags=re.MULTILINE)
        content = re.sub(r'"""[\s\S]*?"""', '', content)
        content = re.sub(r"'''[\s\S]*?'''", '', content)
        content = re.sub(r'"[^"]*"', '', content)
        content = re.sub(r"'[^']*'", '', content)

        # Extract Python tokens: identifiers, keywords, operators
        tokens = re.findall(r'[a-zA-Z_]\w*|[+\-*/=<>!&|^~%]', content)
        return [t for t in tokens if len(t) > 1 or not t.isalpha()]

    @staticmethod
    def _compute_ngrams(tokens: list[str]) -> set[str]:
        """Compute n-gram hashes from a token list."""
        ngrams: set[str] = set()
        for i in range(len(tokens) - DuplicateDetector.NGRAM_SIZE + 1):
            ngram = " ".join(tokens[i:i + DuplicateDetector.NGRAM_SIZE])
            ngrams.add(hashlib.md5(ngram.encode()).hexdigest())
        return ngrams

    @staticmethod
    def _jaccard_similarity(set_a: set[str], set_b: set[str]) -> float:
        """Compute Jaccard similarity between two sets of n-gram hashes."""
        if not set_a or not set_b:
            return 0.0
        intersection = len(set_a & set_b)
        union = len(set_a | set_b)
        return intersection / union if union > 0 else 0.0

import uuid
from datetime import datetime, timezone, timedelta
from pathlib import Path
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa
import jwt as pyjwt

from app.config import Settings

settings = Settings()


def _load_private_key() -> rsa.RSAPrivateKey:
    key_path = Path(settings.jwt_private_key_path)
    if not key_path.exists():
        raise FileNotFoundError(
            f"JWT private key not found at {key_path}. Run 'make keys' first."
        )
    with open(key_path, "rb") as f:
        return serialization.load_pem_private_key(f.read(), password=None)


def _load_public_key() -> rsa.RSAPublicKey:
    key_path = Path(settings.jwt_public_key_path)
    if not key_path.exists():
        raise FileNotFoundError(
            f"JWT public key not found at {key_path}. Run 'make keys' first."
        )
    with open(key_path, "rb") as f:
        return serialization.load_pem_public_key(f.read())


def create_access_token(user_id: uuid.UUID) -> str:
    private_key = _load_private_key()
    now = datetime.now(timezone.utc)
    payload = {
        "sub": str(user_id),
        "type": "access",
        "iat": now,
        "exp": now + timedelta(minutes=settings.jwt_access_token_expire_minutes),
    }
    return pyjwt.encode(payload, private_key, algorithm="RS256")


def create_refresh_token(user_id: uuid.UUID, session_id: uuid.UUID) -> str:
    private_key = _load_private_key()
    now = datetime.now(timezone.utc)
    payload = {
        "sub": str(user_id),
        "sid": str(session_id),
        "type": "refresh",
        "iat": now,
        "exp": now + timedelta(days=settings.jwt_refresh_token_expire_days),
    }
    return pyjwt.encode(payload, private_key, algorithm="RS256")


def verify_access_token(token: str) -> dict | None:
    try:
        public_key = _load_public_key()
        payload = pyjwt.decode(
            token, public_key, algorithms=["RS256"], options={"require": ["sub", "type"]}
        )
        if payload.get("type") != "access":
            return None
        return payload
    except pyjwt.ExpiredSignatureError:
        return None
    except pyjwt.PyJWTError:
        return None


def verify_refresh_token(token: str) -> dict | None:
    try:
        public_key = _load_public_key()
        payload = pyjwt.decode(
            token, public_key, algorithms=["RS256"], options={"require": ["sub", "sid", "type"]}
        )
        if payload.get("type") != "refresh":
            return None
        return payload
    except pyjwt.ExpiredSignatureError:
        return None
    except pyjwt.PyJWTError:
        return None

import time
import math


class RateLimiter:
    """Tracks GitHub API rate limits and coordinates backoff (D-37)."""

    def __init__(self):
        self.remaining: int = 5000
        self.reset_at: float = 0
        self.min_remaining_threshold: int = 100

    def update(self, remaining: int, reset_unix: int) -> None:
        self.remaining = remaining
        self.reset_at = float(reset_unix)

    def is_exhausted(self) -> bool:
        """Return True if rate limit is critically low."""
        return self.remaining <= self.min_remaining_threshold

    def seconds_until_reset(self) -> float:
        """Seconds until rate limit resets. Returns 0 if reset already happened."""
        return max(0, self.reset_at - time.time())

    def wait_time(self) -> float:
        """Calculate recommended wait time before next request."""
        if self.remaining <= 0:
            return min(self.seconds_until_reset() + 1, 3600)
        if self.remaining <= self.min_remaining_threshold:
            # Exponentially back off as we approach exhaustion
            return math.ceil((self.min_remaining_threshold - self.remaining) * 0.5)
        return 0.0

import uuid
from app.celery_app import celery_app
from app.ingestion.pipeline import ingest_repo


@celery_app.task(bind=True, max_retries=3, default_retry_delay=60)
def ingest_repo_task(self, repo_id: str):
    """Celery task: ingest a GitHub repository. Retries with backoff on failure."""
    import asyncio
    try:
        asyncio.run(ingest_repo(uuid.UUID(repo_id)))
    except Exception as exc:
        # Retry with exponential backoff (D-50 checkpoint recovery handles resume)
        raise self.retry(exc=exc, countdown=60 * (2 ** self.request.retries))


@celery_app.task(bind=True)
def retry_ingestion_task(self, repo_id: str):
    """Retry ingestion from last checkpoint (D-50). Same as ingest but status is already 'failed'."""
    # CheckpointManager.should_resume will detect last successful stage
    return ingest_repo_task.delay(repo_id)

"use client";

import {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  ReactNode,
} from "react";
import { User, getMe, logout as apiLogout, refreshTokens } from "@/lib/auth";

interface AuthState {
  user: User | null;
  loading: boolean;
  error: string | null;
  logout: () => Promise<void>;
  refresh: () => Promise<void>;
}

const AuthContext = createContext<AuthState | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const checkSession = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const me = await getMe();
      setUser(me);
    } catch {
      setUser(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    checkSession();
  }, [checkSession]);

  const logout = useCallback(async () => {
    try {
      await apiLogout();
    } catch {
      // Proceed with client-side logout even if API call fails
    }
    setUser(null);
  }, []);

  const refresh = useCallback(async () => {
    try {
      await refreshTokens();
      const me = await getMe();
      setUser(me);
    } catch {
      setUser(null);
    }
  }, []);

  return (
    <AuthContext.Provider
      value={{ user, loading, error, logout, refresh }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth(): AuthState {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

