  const [saveSuccess, setSaveSuccess] = useState(false);
  const [nameError, setNameError] = useState<string | null>(null);

  // ── Duplicating state ──────────────────────────────
  const [duplicating, setDuplicating] = useState(false);

  // ── Fetch project ──────────────────────────────────
  const fetchProject = useCallback(async () => {
    if (!projectId) return;
