"use client";

import { useState } from "react";
import { Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import type { IngestionStatus } from "@/lib/api-repos";

export function IngestButton({
  repoId,
  status,
  onIngest,
  disabled = false,
  disabledReason,
}: {
  repoId: string;
  status: IngestionStatus;
  onIngest: (repoId: string) => Promise<void>;
  disabled?: boolean;
  disabledReason?: string;
}) {
  const [loading, setLoading] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [confirmAction, setConfirmAction] = useState<
    "reingest" | "retry" | null
  >(null);

  const isRunning =
    status === "queued" ||
    status === "fetching_metadata" ||
    status === "cloning" ||
    status === "analyzing";

  async function handleClick() {
    if (isRunning) return;

    if (status === "complete") {
      setConfirmAction("reingest");
      setShowConfirm(true);
      return;
    }

    if (status === "failed" || status === "paused") {
      setConfirmAction("retry");
      setShowConfirm(true);
      return;
    }

    // pending — start ingestion
    setLoading(true);
    try {
      await onIngest(repoId);
    } finally {
      setLoading(false);
    }
  }

  async function handleConfirm() {
    setShowConfirm(false);
    setLoading(true);
    try {
      await onIngest(repoId);
    } finally {
      setLoading(false);
    }
  }

  // ── Tooltip helper ──────────────────────────────
  function maybeTooltip(button: React.ReactNode) {
    if (disabled && !loading && disabledReason) {
      return (
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger>
              <span tabIndex={0}>{button}</span>
            </TooltipTrigger>
            <TooltipContent>
              <p>{disabledReason}</p>
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>
      );
    }
    return <>{button}</>;
  }

  // ── Button rendering ────────────────────────────

  if (isRunning) {
    return (
      <TooltipProvider>
        <Tooltip>
              <TooltipTrigger>
                <span tabIndex={0}>
                  <Button disabled className="cursor-not-allowed">
                    <Loader2 className="size-3.5 mr-1.5 animate-spin" />
                    Ingesting…
                  </Button>
                </span>
              </TooltipTrigger>
          <TooltipContent>
            <p>Ingestion already in progress</p>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    );
  }

  if (status === "complete") {
    return (
      <>
        {maybeTooltip(
          <Button
            variant="default"
            onClick={handleClick}
            disabled={disabled || loading}
            className="bg-[#10B981] hover:bg-[#10B981]/80 text-white"
          >
            {loading ? (
              <>
                <Loader2 className="size-3.5 mr-1.5 animate-spin" />
                Re-ingesting…
              </>
            ) : (
              "Re-ingest"
            )}
          </Button>
        )}
        {showConfirm && confirmAction === "reingest" && (
          <ReIngestConfirmDialog
            onConfirm={handleConfirm}
            onCancel={() => setShowConfirm(false)}
          />
        )}
      </>
    );
  }

  if (status === "failed" || status === "paused") {
    return (
      <>
        {maybeTooltip(
          <Button
            variant="destructive"
            onClick={handleClick}
            disabled={disabled || loading}
          >
            {loading ? (
              <>
                <Loader2 className="size-3.5 mr-1.5 animate-spin" />
                Retrying…
              </>
            ) : (
              "Retry"
            )}
          </Button>
        )}
        {showConfirm && confirmAction === "retry" && (
          <RetryConfirmDialog
            onConfirm={handleConfirm}
            onCancel={() => setShowConfirm(false)}
          />
        )}
      </>
    );
  }

  // Default: pending
  return maybeTooltip(
    <Button
      variant="default"
      onClick={handleClick}
      disabled={disabled || loading}
    >
      {loading ? (
        <>
          <Loader2 className="size-3.5 mr-1.5 animate-spin" />
          Ingesting…
        </>
      ) : (
        "Ingest Repository"
      )}
    </Button>
  );
}

